WITH RECURSIVE split(expense_id, rest, item) AS (
  SELECT x.expense_id, x.expense_description || ',', '' FROM expense x JOIN budget b ON b.budget_id = x.link_to_budget WHERE b.category = 'Food' AND x.expense_description IS NOT NULL
  UNION ALL
  SELECT expense_id, substr(rest, instr(rest, ',') + 1), trim(substr(rest, 1, instr(rest, ',') - 1)) FROM split WHERE rest <> ''
)
SELECT MIN(item) AS item, COUNT(DISTINCT expense_id) AS records FROM split WHERE item <> '' GROUP BY LOWER(item) ORDER BY records DESC, LOWER(item) ASC LIMIT 1;

WITH RECURSIVE split(eid, rest, item) AS (
  SELECT x.expense_id, x.expense_description || ',', '' FROM expense x JOIN budget b ON b.budget_id = x.link_to_budget WHERE b.category = 'Food'
  UNION ALL
  SELECT eid, substr(rest, instr(rest, ',') + 1), trim(substr(rest, 1, instr(rest, ',') - 1)) FROM split WHERE rest <> ''
)
SELECT LOWER(item) AS item, COUNT(DISTINCT eid) AS record_count FROM split WHERE item <> '' GROUP BY LOWER(item) ORDER BY record_count DESC, item ASC LIMIT 1;

WITH plus_atoms AS (
  SELECT a.atom_id, a.element FROM atom AS a JOIN molecule AS m ON m.molecule_id = a.molecule_id WHERE m.label = '+'
),
bonded_counts AS (
  SELECT element, COUNT(*) AS bonded_n FROM plus_atoms
  WHERE atom_id IN (SELECT atom_id FROM connected UNION SELECT atom_id2 FROM connected)
  GROUP BY element
),
top AS (
  SELECT element FROM bonded_counts WHERE bonded_n = (SELECT MAX(bonded_n) FROM bonded_counts)
)
SELECT t.element, ROUND(100.0 * (SELECT COUNT(*) FROM plus_atoms AS p WHERE p.element = t.element) / (SELECT COUNT(*) FROM plus_atoms), 2) AS percentage
FROM top AS t ORDER BY t.element;

WITH gold_accts AS (
  SELECT DISTINCT d.account_id FROM card c JOIN disp d ON d.disp_id = c.disp_id WHERE c.type = 'gold' AND d.type = 'OWNER'
), big_branch AS (
  SELECT a.account_id FROM account a JOIN district di ON di.district_id = a.district_id WHERE CAST(di.A4 AS INTEGER) >= 250000
), pays AS (
  SELECT t.bank, t.account, t.amount FROM trans t
  WHERE t.type = 'VYDAJ' AND t.date >= '1998-01-01' AND t.date <= '1998-12-31'
    AND t.bank IS NOT NULL AND t.account IS NOT NULL
    AND t.account_id IN (SELECT account_id FROM gold_accts)
    AND t.account_id IN (SELECT account_id FROM big_branch)
), agg AS (
  SELECT bank, account, COUNT(*) AS payment_count, SUM(amount) AS total_paid FROM pays GROUP BY bank, account
)
SELECT bank, account, payment_count, total_paid FROM agg WHERE total_paid = (SELECT MAX(total_paid) FROM agg) ORDER BY bank, account;

WITH winners AS (
  SELECT r.year AS year, r.raceId AS raceId, MIN(x.milliseconds) AS ms
  FROM results AS x JOIN races AS r ON r.raceId = x.raceId
  WHERE x.positionOrder = 1 AND x.milliseconds IS NOT NULL AND r.year < 1975
  GROUP BY r.raceId
), agg AS (
  SELECT year, SUM(ms) AS total_ms, COUNT(*) AS n FROM winners GROUP BY year
)
SELECT year, CAST((total_ms + 5 * n) / (10 * n) AS REAL) / 100.0 AS mean_winner_seconds FROM agg ORDER BY year;

WITH slots AS (
SELECT country_id, home_player_1 AS pid FROM Match UNION ALL SELECT country_id, home_player_2 FROM Match UNION ALL SELECT country_id, home_player_3 FROM Match UNION ALL SELECT country_id, home_player_4 FROM Match UNION ALL SELECT country_id, home_player_5 FROM Match UNION ALL SELECT country_id, home_player_6 FROM Match UNION ALL SELECT country_id, home_player_7 FROM Match UNION ALL SELECT country_id, home_player_8 FROM Match UNION ALL SELECT country_id, home_player_9 FROM Match UNION ALL SELECT country_id, home_player_10 FROM Match UNION ALL SELECT country_id, home_player_11 FROM Match UNION ALL
SELECT country_id, away_player_1 FROM Match UNION ALL SELECT country_id, away_player_2 FROM Match UNION ALL SELECT country_id, away_player_3 FROM Match UNION ALL SELECT country_id, away_player_4 FROM Match UNION ALL SELECT country_id, away_player_5 FROM Match UNION ALL SELECT country_id, away_player_6 FROM Match UNION ALL SELECT country_id, away_player_7 FROM Match UNION ALL SELECT country_id, away_player_8 FROM Match UNION ALL SELECT country_id, away_player_9 FROM Match UNION ALL SELECT country_id, away_player_10 FROM Match UNION ALL SELECT country_id, away_player_11 FROM Match
),
heavy AS (
SELECT s.country_id, s.pid FROM slots s JOIN Player p ON p.player_api_id = s.pid WHERE s.pid IS NOT NULL AND p.weight >= 210
),
counts AS (
SELECT c.name AS country, COUNT(*) AS qualifying_players FROM heavy h JOIN Country c ON c.id = h.country_id GROUP BY c.id, c.name
)
SELECT country, qualifying_players FROM counts WHERE qualifying_players = (SELECT MAX(qualifying_players) FROM counts) ORDER BY country;

WITH plus_atoms AS (
  SELECT a.atom_id, a.element FROM atom AS a JOIN molecule AS m ON m.molecule_id = a.molecule_id WHERE m.label = '+'
),
bonded_atoms AS (
  SELECT atom_id AS id FROM connected UNION SELECT atom_id2 FROM connected
),
bonded_counts AS (
  SELECT p.element, COUNT(*) AS bonded_n FROM plus_atoms AS p WHERE p.atom_id IN (SELECT id FROM bonded_atoms) GROUP BY p.element
),
all_counts AS (
  SELECT element, COUNT(*) AS total_n FROM plus_atoms GROUP BY element
),
totals AS (SELECT COUNT(*) AS grand FROM plus_atoms),
ranked AS (
  SELECT b.element, b.bonded_n, RANK() OVER (ORDER BY b.bonded_n DESC) AS rk FROM bonded_counts AS b
)
SELECT r.element, ROUND(100.0 * ac.total_n / t.grand, 2) AS pct_of_all_atoms
FROM ranked AS r JOIN all_counts AS ac ON ac.element = r.element CROSS JOIN totals AS t
WHERE r.rk = 1
ORDER BY r.element;

WITH slots AS (
SELECT country_id, home_player_1 AS pid FROM Match UNION ALL SELECT country_id, home_player_2 FROM Match UNION ALL SELECT country_id, home_player_3 FROM Match UNION ALL SELECT country_id, home_player_4 FROM Match UNION ALL SELECT country_id, home_player_5 FROM Match UNION ALL SELECT country_id, home_player_6 FROM Match UNION ALL SELECT country_id, home_player_7 FROM Match UNION ALL SELECT country_id, home_player_8 FROM Match UNION ALL SELECT country_id, home_player_9 FROM Match UNION ALL SELECT country_id, home_player_10 FROM Match UNION ALL SELECT country_id, home_player_11 FROM Match UNION ALL
SELECT country_id, away_player_1 FROM Match UNION ALL SELECT country_id, away_player_2 FROM Match UNION ALL SELECT country_id, away_player_3 FROM Match UNION ALL SELECT country_id, away_player_4 FROM Match UNION ALL SELECT country_id, away_player_5 FROM Match UNION ALL SELECT country_id, away_player_6 FROM Match UNION ALL SELECT country_id, away_player_7 FROM Match UNION ALL SELECT country_id, away_player_8 FROM Match UNION ALL SELECT country_id, away_player_9 FROM Match UNION ALL SELECT country_id, away_player_10 FROM Match UNION ALL SELECT country_id, away_player_11 FROM Match
), counts AS (
SELECT c.name AS country, COUNT(DISTINCT s.pid) AS players FROM slots s JOIN Player p ON p.player_api_id = s.pid JOIN Country c ON c.id = s.country_id WHERE p.weight >= 210 GROUP BY c.name
)
SELECT country, players FROM counts WHERE players = (SELECT MAX(players) FROM counts) ORDER BY country;

WITH plus_atoms AS (
  SELECT a.atom_id, a.element FROM atom AS a JOIN molecule AS m ON m.molecule_id = a.molecule_id WHERE m.label = '+'
),
bonded_atoms AS (
  SELECT atom_id AS atom_id FROM connected UNION SELECT atom_id2 FROM connected
),
bonded_counts AS (
  SELECT p.element, COUNT(*) AS bonded_n FROM plus_atoms AS p WHERE p.atom_id IN (SELECT atom_id FROM bonded_atoms) GROUP BY p.element
),
top AS (
  SELECT element FROM bonded_counts WHERE bonded_n = (SELECT MAX(bonded_n) FROM bonded_counts)
),
total AS (SELECT COUNT(*) AS n FROM plus_atoms)
SELECT t.element AS element, ROUND(100.0 * (SELECT COUNT(*) FROM plus_atoms p WHERE p.element = t.element) / (SELECT n FROM total), 2) AS pct_of_all_atoms
FROM top AS t ORDER BY t.element;

WITH rnp_pts AS (SELECT DISTINCT ID FROM Laboratory WHERE CAST(RNP AS REAL) >= 16),
gpt_stats AS (
  SELECT l.ID, COUNT(l.GPT) AS n_gpt, SUM(CASE WHEN l.GPT >= 60 THEN 1 ELSE 0 END) AS n_high, MAX(CASE WHEN l.GPT < 60 THEN l.GPT END) AS max_normal_gpt
  FROM Laboratory AS l WHERE l.ID IN (SELECT ID FROM rnp_pts) GROUP BY l.ID
)
SELECT p.Birthday FROM Patient AS p JOIN gpt_stats AS g ON g.ID = p.ID WHERE g.n_gpt > 0 AND g.n_high = 0 ORDER BY g.max_normal_gpt DESC, p.ID ASC LIMIT 3;

SELECT l.ID, CAST(l.RNP AS INTEGER) AS RNP
FROM Laboratory AS l
WHERE l.ID IN (
  SELECT l2.ID FROM Laboratory AS l2 JOIN Patient AS p ON p.ID = l2.ID
  WHERE p.Admission = '-' AND l2.SSA IN ('1','4','16','64','256')
)
AND CAST(l.RNP AS INTEGER) = (
  SELECT MAX(CAST(l3.RNP AS INTEGER)) FROM Laboratory AS l3
  WHERE l3.ID IN (
    SELECT l4.ID FROM Laboratory AS l4 JOIN Patient AS p2 ON p2.ID = l4.ID
    WHERE p2.Admission = '-' AND l4.SSA IN ('1','4','16','64','256')
  )
);

WITH org AS (
  SELECT b.UserId, b.Date AS odate FROM badges b JOIN users u ON u.Id = b.UserId
  WHERE b.Name = 'Organizer' AND u.Location LIKE '%Germany%'
),
prior AS (
  SELECT o.UserId, COUNT(b.Id) AS n FROM org o
  LEFT JOIN badges b ON b.UserId = o.UserId AND b.Date < o.odate AND b.Name <> 'Organizer'
  GROUP BY o.UserId
)
SELECT COUNT(*) FROM prior WHERE n >= 5;

WITH virt AS (
  SELECT CDSCode, County, School FROM schools WHERE Virtual = 'F' AND School IS NOT NULL
),
cnt AS (
  SELECT County, COUNT(*) AS n FROM virt GROUP BY County
),
top AS (
  SELECT County, n FROM cnt WHERE n >= (SELECT n FROM cnt ORDER BY n DESC LIMIT 1 OFFSET 4)
),
best AS (
  SELECT v.County, v.School, sat.AvgScrRead AS read_avg FROM virt AS v JOIN satscores AS sat ON sat.cds = v.CDSCode AND sat.rtype = 'S' WHERE sat.AvgScrRead IS NOT NULL
),
maxr AS (
  SELECT County, MAX(read_avg) AS mx FROM best GROUP BY County
),
topschool AS (
  SELECT b.County, b.School FROM best AS b JOIN maxr AS m ON m.County = b.County AND b.read_avg = m.mx
)
SELECT t.County AS county, t.n AS exclusively_virtual_schools, COALESCE(ts.School, 'None') AS top_reading_school
FROM top AS t LEFT JOIN topschool AS ts ON ts.County = t.County
ORDER BY t.n DESC, t.County, ts.School;

WITH gold_accounts AS (
  SELECT DISTINCT d.account_id FROM disp AS d JOIN card AS c ON c.disp_id = d.disp_id WHERE d.type = 'OWNER' AND c.type = 'gold'
), big_branch_accounts AS (
  SELECT a.account_id FROM account AS a JOIN district AS di ON di.district_id = a.district_id WHERE CAST(di.A4 AS INTEGER) >= 250000
), payments AS (
  SELECT t.bank, t.account, t.amount FROM trans AS t
  WHERE t.type = 'VYDAJ' AND t.date >= '1998-01-01' AND t.date < '1999-01-01'
    AND t.bank IS NOT NULL AND t.account > 0
    AND t.account_id IN (SELECT account_id FROM gold_accounts)
    AND t.account_id IN (SELECT account_id FROM big_branch_accounts)
), totals AS (
  SELECT bank, account, COUNT(*) AS payment_count, SUM(amount) AS total_paid FROM payments GROUP BY bank, account
)
SELECT bank, account, payment_count, total_paid FROM totals WHERE total_paid = (SELECT MAX(total_paid) FROM totals);

WITH ext AS (
  SELECT player_api_id, player_name FROM Player
  WHERE height = (SELECT MAX(height) FROM Player) OR height = (SELECT MIN(height) FROM Player)
), avgf AS (
  SELECT e.player_name, AVG(a.finishing) AS avg_fin
  FROM ext e JOIN Player_Attributes a ON a.player_api_id = e.player_api_id
  GROUP BY e.player_api_id, e.player_name
)
SELECT player_name FROM avgf ORDER BY avg_fin DESC LIMIT 1;

WITH lineup AS (
