),
light AS (
SELECT DISTINCT l.country_id, l.pid FROM lineup AS l INNER JOIN Player AS p ON p.player_api_id = l.pid WHERE l.pid IS NOT NULL AND p.weight <= 160
),
counts AS (
SELECT c.name AS country_name, COUNT(DISTINCT x.pid) AS players FROM Country AS c LEFT JOIN light AS x ON x.country_id = c.id GROUP BY c.id, c.name
)
SELECT country_name, players FROM counts WHERE players = (SELECT MIN(players) FROM counts) ORDER BY country_name
